class Solution:
    def findMedianSortedArrays(self, nums1: list[int], nums2: list[int]) -> float:
        nums = []
        m, n = len(nums1), len(nums2)
        i, j = 0, 0

        while i < m and j < n:
            if nums1[i] <= nums2[j]:
                nums.append(nums1[i])
                i += 1
            else:
                nums.append(nums2[j])
                j += 1

        while i < m:
            nums.append(nums1[i])
            i += 1
        while j < n:
            nums.append(nums2[j])
            j += 1

        if (m + n) % 2 == 1:
            return nums[(m + n) // 2]

        return (nums[(m + n) // 2] + nums[(m + n) // 2 - 1]) / 2
